#include <iostream>
#include <memory>
#include <utility>
#include <stdexcept>

// Singly linked list implementing core dynamic storage
template <typename T>
class LinkedList {
private:
    struct Node {
        T data;
        std::unique_ptr<Node> next;
        Node(T val) : data(std::move(val)), next(nullptr) {}
    };
    std::unique_ptr<Node> head;
    Node* tail = nullptr;

public:
    LinkedList() = default;
    bool isEmpty() const noexcept { return head == nullptr; }

    void pushBack(T val) {
        auto newNode = std::make_unique<Node>(std::move(val));
        Node* rawNew = newNode.get();
        if (!tail) {
            head = std::move(newNode);
            tail = rawNew;
        } else {
            tail->next = std::move(newNode);
            tail = rawNew;
        }
    }

    T popFront() {
        if (isEmpty()) throw std::runtime_error("List is empty");
        T value = std::move(head->data);
        head = std::move(head->next);
        if (!head) tail = nullptr;
        return value;
    }
};

// Queue implemented via Composition (reusing LinkedList)
template <typename T>
class Queue {
private:
    LinkedList<T> list; // Composition: 'has-a' relationship

public:
    bool empty() const noexcept { return list.isEmpty(); }
    void enqueue(T val) { list.pushBack(std::move(val)); }
    T dequeue() { return list.popFront(); }
};

int main() {
    Queue<int> q;
    q.enqueue(10);
    q.enqueue(20);
    q.enqueue(30);

    while (!q.empty()) {
        std::cout << q.dequeue() << " ";
    }
    std::cout << "\n";
    return 0;
}

#include <iostream>
#include <memory>
#include <queue>

struct TreeNode {
    int val;
    std::unique_ptr<TreeNode> left;
    std::unique_ptr<TreeNode> right;
    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}
};

void insert(std::unique_ptr<TreeNode>& node, int val) {
    if (!node) {
        node = std::make_unique<TreeNode>(val);
    } else if (val < node->val) {
        insert(node->left, val);
    } else if (val > node->val) {
        insert(node->right, val);
    }
    // Duplicates are discarded
}

void inorder(const TreeNode* node) {
    if (!node) return;
    inorder(node->left.get());
    std::cout << node->val << " ";
    inorder(node->right.get());
}

void preorder(const TreeNode* node) {
    if (!node) return;
    std::cout << node->val << " ";
    preorder(node->left.get());
    preorder(node->right.get());
}

void postorder(const TreeNode* node) {
    if (!node) return;
    postorder(node->left.get());
    postorder(node->right.get());
    std::cout << node->val << " ";
}

void levelOrder(const TreeNode* root) {
    if (!root) return;
    std::queue<const TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
        const TreeNode* curr = q.front();
        q.pop();
        std::cout << curr->val << " ";
        if (curr->left) q.push(curr->left.get());
        if (curr->right) q.push(curr->right.get());
    }
}

int main() {
    std::unique_ptr<TreeNode> root = nullptr;
    // Subtree from Fig 19.24: 49, 28, 83, 18, 40
    for (int v : {49, 28, 83, 18, 40}) {
        insert(root, v);
    }

    std::cout << "Inorder: ";
    inorder(root.get());
    std::cout << "\nPreorder: ";
    preorder(root.get());
    std::cout << "\nPostorder: ";
    postorder(root.get());
    std::cout << "\nLevel-order: ";
    levelOrder(root.get());
    std::cout << "\n";
    return 0;
}
